class Program {
    public static int[] TopKFrequent(int[] nums, int k) {
        var map = new Dictionary<int, int>();
        foreach (int n in nums) {
            if (!map.ContainsKey(n)) map[n] = 0;
            map[n]++;
        }
        return map.OrderByDescending(x => x.Value).Take(k).Select(x => x.Key).ToArray();
